create or replace function public.queue_enrichment(w uuid,lead uuid,permission boolean) returns uuid language plpgsql security definer set search_path=public as $$declare result uuid;begin perform require_member(w);if workspace_role(w)='Agent' then raise exception 'Manager or admin required';end if;if not permission then raise exception 'Explicit crawl permission required';end if;if not exists(select 1 from leads where workspace_id=w and id=lead and coalesce(data->>'website','')<>'') then raise exception 'Business website required';end if;insert into jobs(workspace_id,kind,payload,unique_key) values(w,'enrichment',jsonb_build_object('lead_id',lead,'crawl_permission',true),'enrich:'||lead::text||':'||date_trunc('day',now())::text) on conflict(workspace_id,unique_key) do update set payload=excluded.payload returning id into result;return result;end$$;
revoke all on function public.queue_enrichment(uuid,uuid,boolean) from public,anon;
grant execute on function public.queue_enrichment(uuid,uuid,boolean) to authenticated,service_role;
